/* Self-hosted DM Mono / Rift / Rubik, split out of index.html.
   Self-hosted on purpose so the site works with no internet. */
@font-face {
    font-family: 'Rubik';
    font-style: normal;
    font-weight: 400;
    font-display: swap;
    src: url(data:font/woff2;base64,) format('woff2');
  }
@font-face {
    font-family: 'Rubik';
    font-style: normal;
    font-weight: 500;
    font-display: swap;
    src: url(data:font/woff2;base64,) format('woff2');
  }
